(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  function setVal(el, v) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
  }
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth)$/.test(i.id||''));
  if (!boxes.length) return JSON.stringify({stage:'noBoxes', url: location.href});
  const digits = '8751';
  for (let i=0;i<boxes.length;i++) setVal(boxes[i], i < digits.length ? digits[i] : '');
  await sleep(400);
  const loginBtn = Array.from(document.querySelectorAll('button')).find(b => /^login$/i.test((b.innerText||'').replace(/\s+/g,' ').trim()) && b.offsetParent!==null);
  if (loginBtn) loginBtn.click();
  await sleep(12000);
  return JSON.stringify({url: location.href,
    txt: (document.body.innerText||'').replace(/\s+/g,' ').slice(0,320),
    errs: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/wrong|invalid|incorrect|failed|mismatch/i.test(t) && t.length<100).slice(0,3)),
    visBtns: Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean).filter(t=>/login|web|trader|continue|try/i.test(t)).slice(0,6)});
})()
